package memorylooptui

import (
	"fmt"
	"strconv"
	"strings"

	"github.com/charmbracelet/bubbles/key"
	"github.com/charmbracelet/bubbles/table"
	"github.com/charmbracelet/bubbles/textinput"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/entireio/cli/cmd/entire/cli/memoryloop"
)

type statusFilter int

const (
	filterAll statusFilter = iota
	filterActive
	filterCandidate
	filterSuppressed
	filterArchived
)

var filterLabels = [5]string{"ALL", "ACTIVE", "CANDIDATE", "SUPPRESSED", "ARCHIVED"}

type scopeFilter int

const (
	scopeAll scopeFilter = iota
	scopeRepo
	scopeMe
	scopeBranch
)

var scopeFilterLabels = [4]string{"All", "Repo", "Me", "Branch"}

//nolint:recvcheck // bubbletea pattern: pointer receivers for mutation, value for update/view
type memoriesModel struct {
	state      *memoryloop.State
	styles     tuiStyles
	width      int
	height     int
	table      table.Model
	filter     statusFilter
	scopeFltr  scopeFilter
	showDetail bool
	searchMode bool
	searchText string
	records    []memoryloop.MemoryRecord // filtered subset
	addMode    bool
	addFields  [4]textinput.Model // kind, title, body, scope
	addFocus   int
}

func newMemoriesModel(s tuiStyles) memoriesModel {
	columns := []table.Column{
		{Title: " ", Width: 2},
		{Title: "Title", Width: 30},
		{Title: "Kind", Width: 14},
		{Title: "Scope", Width: 5},
		{Title: "Str", Width: 5},
		{Title: "Outcome", Width: 11},
		{Title: "Inj", Width: 4},
	}
	t := table.New(
		table.WithColumns(columns),
		table.WithFocused(true),
	)
	st := table.DefaultStyles()
	st.Header = st.Header.
		BorderStyle(lipgloss.NormalBorder()).
		BorderBottom(true).
		Bold(false).
		Faint(true)
	st.Selected = st.Selected.
		Foreground(lipgloss.Color("214")).
		Bold(false)
	t.SetStyles(st)

	return memoriesModel{
		styles:     s,
		table:      t,
		showDetail: true,
	}
}

// capturesInput returns true when the memories tab is handling keyboard input
// internally (add form or search mode), so the root model should skip global keys.
func (m memoriesModel) capturesInput() bool {
	return m.addMode || m.searchMode
}

func newAddFields() [4]textinput.Model {
	kind := textinput.New()
	kind.Placeholder = "repo_rule | workflow_rule | agent_instruction | skill_patch | anti_pattern"
	kind.Prompt = "Kind: "
	kind.Width = 60

	title := textinput.New()
	title.Placeholder = "memory title"
	title.Prompt = "Title: "
	title.Width = 60

	body := textinput.New()
	body.Placeholder = "memory body"
	body.Prompt = "Body: "
	body.Width = 60

	scope := textinput.New()
	scope.Placeholder = "me | repo"
	scope.Prompt = "Scope: "
	scope.Width = 20
	scope.SetValue("me")

	return [4]textinput.Model{kind, title, body, scope}
}

func (m *memoriesModel) setState(state *memoryloop.State) {
	m.state = state
	m.rebuildTable()
}

func (m *memoriesModel) setSize(w, h int) {
	m.width = w
	m.height = h
	// Reserve 3 lines for filter bar + detail pane header area
	tableH := h - 3
	if m.showDetail {
		tableH = h / 2
	}
	if tableH < 3 {
		tableH = 3
	}
	m.table.SetWidth(w)
	m.table.SetHeight(tableH)
}

func (m *memoriesModel) rebuildTable() {
	if m.state == nil || m.state.Store == nil {
		m.records = nil
		m.table.SetRows(nil)
		return
	}

	var filtered []memoryloop.MemoryRecord
	for _, r := range m.state.Store.Records {
		if !m.matchesFilter(r) {
			continue
		}
		if m.searchMode && m.searchText != "" {
			if !strings.Contains(strings.ToLower(r.Title), strings.ToLower(m.searchText)) {
				continue
			}
		}
		filtered = append(filtered, r)
	}
	m.records = filtered

	rows := make([]table.Row, len(filtered))
	for i, r := range filtered {
		rows[i] = table.Row{
			statusDotPlain(r.Status),
			truncate(r.Title, 30),
			string(r.Kind),
			string(r.ScopeKind),
			renderStrengthBar(r.Strength),
			string(r.Outcome),
			strconv.Itoa(r.InjectCount),
		}
	}
	m.table.SetRows(rows)
}

func (m memoriesModel) matchesFilter(r memoryloop.MemoryRecord) bool {
	return m.matchesStatusFilter(r) && m.matchesScopeFilter(r)
}

func (m memoriesModel) matchesStatusFilter(r memoryloop.MemoryRecord) bool {
	switch m.filter {
	case filterAll:
		return true
	case filterActive:
		return r.Status == memoryloop.StatusActive
	case filterCandidate:
		return r.Status == memoryloop.StatusCandidate
	case filterSuppressed:
		return r.Status == memoryloop.StatusSuppressed
	case filterArchived:
		return r.Status == memoryloop.StatusArchived
	default:
		return true
	}
}

func (m memoriesModel) matchesScopeFilter(r memoryloop.MemoryRecord) bool {
	switch m.scopeFltr {
	case scopeAll:
		return true
	case scopeRepo:
		return r.ScopeKind == memoryloop.ScopeKindRepo
	case scopeMe:
		return r.ScopeKind == memoryloop.ScopeKindMe
	case scopeBranch:
		return r.ScopeKind == memoryloop.ScopeKindBranch
	default:
		return true
	}
}

func (m memoriesModel) selectedRecord() *memoryloop.MemoryRecord {
	cursor := m.table.Cursor()
	if cursor < 0 || cursor >= len(m.records) {
		return nil
	}
	return &m.records[cursor]
}

func (m memoriesModel) update(msg tea.Msg) (memoriesModel, tea.Cmd) {
	if keyMsg, ok := msg.(tea.KeyMsg); ok {
		if m.addMode {
			return m.updateAddForm(keyMsg)
		}

		if m.searchMode {
			return m.updateSearch(keyMsg)
		}

		switch {
		case key.Matches(keyMsg, memoriesKeyMap.New):
			m.addMode = true
			m.addFields = newAddFields()
			m.addFocus = 0
			m.addFields[0].Focus()
			return m, textinput.Blink

		case key.Matches(keyMsg, memoriesKeyMap.Filter):
			m.filter = (m.filter + 1) % 5
			m.rebuildTable()
			return m, nil

		case key.Matches(keyMsg, memoriesKeyMap.ScopeFilter):
			m.scopeFltr = (m.scopeFltr + 1) % 4
			m.rebuildTable()
			return m, nil

		case key.Matches(keyMsg, memoriesKeyMap.Search):
			m.searchMode = true
			m.searchText = ""
			return m, nil

		case key.Matches(keyMsg, memoriesKeyMap.Enter):
			if r := m.selectedRecord(); r != nil {
				return m, func() tea.Msg {
					return wizardOpenMsg{record: *r}
				}
			}
			return m, nil

		case key.Matches(keyMsg, memoriesKeyMap.Wizard):
			if r := m.selectedRecord(); r != nil {
				return m, func() tea.Msg {
					return wizardOpenMsg{record: *r}
				}
			}

		case key.Matches(keyMsg, memoriesKeyMap.Prune):
			return m, func() tea.Msg { return pruneMsg{} }
		}
	}

	// Delegate to table for navigation
	var cmd tea.Cmd
	m.table, cmd = m.table.Update(msg)
	return m, cmd
}

func (m memoriesModel) updateSearch(msg tea.KeyMsg) (memoriesModel, tea.Cmd) {
	switch {
	case key.Matches(msg, memoriesKeyMap.Escape):
		m.searchMode = false
		m.searchText = ""
		m.rebuildTable()
		return m, nil
	case msg.Type == tea.KeyEnter:
		m.searchMode = false
		return m, nil
	case msg.Type == tea.KeyBackspace:
		if len(m.searchText) > 0 {
			runes := []rune(m.searchText)
			m.searchText = string(runes[:len(runes)-1])
			m.rebuildTable()
		}
		return m, nil
	default:
		if len(msg.Runes) > 0 {
			m.searchText += string(msg.Runes)
			m.rebuildTable()
		}
		return m, nil
	}
}

func (m memoriesModel) updateAddForm(msg tea.KeyMsg) (memoriesModel, tea.Cmd) {
	switch {
	case key.Matches(msg, memoriesKeyMap.Escape):
		m.addMode = false
		return m, nil

	case msg.String() == "tab":
		// Blur current, advance focus, focus next
		m.addFields[m.addFocus].Blur()
		m.addFocus = (m.addFocus + 1) % len(m.addFields)
		m.addFields[m.addFocus].Focus()
		return m, textinput.Blink

	case msg.String() == "shift+tab":
		m.addFields[m.addFocus].Blur()
		m.addFocus = (m.addFocus + len(m.addFields) - 1) % len(m.addFields)
		m.addFields[m.addFocus].Focus()
		return m, textinput.Blink

	case msg.String() == "enter":
		if m.addFocus < len(m.addFields)-1 {
			// Not on last field -- advance to next
			m.addFields[m.addFocus].Blur()
			m.addFocus++
			m.addFields[m.addFocus].Focus()
			return m, textinput.Blink
		}
		// On last field -- submit
		input := memoryloop.ManualRecordInput{
			Kind:       memoryloop.Kind(m.addFields[0].Value()),
			Title:      m.addFields[1].Value(),
			Body:       m.addFields[2].Value(),
			ScopeKind:  memoryloop.ScopeKind(m.addFields[3].Value()),
			ScopeValue: "",
		}
		m.addMode = false
		return m, func() tea.Msg { return addMemoryMsg{input: input} }
	}

	// Delegate to the focused text input for character input
	var cmd tea.Cmd
	m.addFields[m.addFocus], cmd = m.addFields[m.addFocus].Update(msg)
	return m, cmd
}

func (m memoriesModel) view() string {
	if m.addMode {
		return m.renderAddForm()
	}

	if m.state == nil || m.state.Store == nil {
		return "\n  No memory store found. Switch to History tab and press R to refresh.\n"
	}
	if len(m.state.Store.Records) == 0 {
		return "\n  No memories yet. Press n to add one, or switch to History tab and press R to refresh.\n"
	}

	var b strings.Builder

	// Blank line for spacing between tab bar and filter bar
	b.WriteString("\n")

	// Filter bar
	b.WriteString(m.renderFilterBar())
	b.WriteString("\n\n")

	// Search bar (if active)
	if m.searchMode {
		fmt.Fprintf(&b, "  / %s\u2588\n", m.searchText)
	}

	if len(m.records) == 0 {
		b.WriteString("\n")
		fmt.Fprintf(&b, "  No %s / %s memories. Press f or S to change filter.\n",
			filterLabels[m.filter], scopeFilterLabels[m.scopeFltr])
		return b.String()
	}

	// Table
	b.WriteString(m.table.View())

	// Detail pane with spacing above
	if m.showDetail {
		b.WriteString("\n\n")
		b.WriteString(m.renderDetail())
	}

	return b.String()
}

func (m memoriesModel) renderAddForm() string {
	var b strings.Builder
	b.WriteString("\n  ")
	b.WriteString(m.styles.render(m.styles.title, "NEW MEMORY"))
	b.WriteString("\n\n")
	for i := range m.addFields {
		b.WriteString("  ")
		b.WriteString(m.addFields[i].View())
		b.WriteString("\n")
	}
	b.WriteString("\n  ")
	b.WriteString(m.styles.render(m.styles.dim, "Tab next field | Enter submit | Esc cancel"))
	b.WriteString("\n")
	return b.String()
}

func (m memoriesModel) renderFilterBar() string {
	statusRow := "  " + m.styles.render(m.styles.sectionHeader, "Status") + "  " +
		strings.Join(m.renderStatusFilterChips(), " ")
	scopeRow := "  " + m.styles.render(m.styles.sectionHeader, "Scope") + "   " +
		strings.Join(m.renderScopeFilterChips(), " ")
	return statusRow + "\n" + scopeRow
}

func (m memoriesModel) renderStatusFilterChips() []string {
	statusCounts := m.statusCounts()
	parts := make([]string, 0, len(filterLabels))
	for i, label := range filterLabels {
		text := fmt.Sprintf("%s (%d)", label, statusCounts[i])
		if m.styles.colorEnabled {
			if statusFilter(i) == m.filter {
				parts = append(parts, m.styles.filterChipActive.Render(text))
			} else {
				parts = append(parts, m.styles.filterChipInactive.Render(text))
			}
			continue
		}
		if statusFilter(i) == m.filter {
			parts = append(parts, "["+text+"]")
		} else {
			parts = append(parts, text)
		}
	}
	return parts
}

func (m memoriesModel) renderScopeFilterChips() []string {
	scopeCounts := m.scopeCounts()
	parts := make([]string, 0, len(scopeFilterLabels))
	for i, label := range scopeFilterLabels {
		text := fmt.Sprintf("%s (%d)", label, scopeCounts[i])
		if m.styles.colorEnabled {
			if scopeFilter(i) == m.scopeFltr {
				parts = append(parts, m.styles.filterChipActive.Render(text))
			} else {
				parts = append(parts, m.styles.filterChipInactive.Render(text))
			}
			continue
		}
		if scopeFilter(i) == m.scopeFltr {
			parts = append(parts, "["+text+"]")
		} else {
			parts = append(parts, text)
		}
	}
	return parts
}

func (m memoriesModel) statusCounts() [5]int {
	var counts [5]int
	if m.state == nil || m.state.Store == nil {
		return counts
	}
	for _, r := range m.state.Store.Records {
		if !m.matchesScopeFilter(r) {
			continue
		}
		counts[0]++ // all
		switch r.Status {
		case memoryloop.StatusActive:
			counts[1]++
		case memoryloop.StatusCandidate:
			counts[2]++
		case memoryloop.StatusSuppressed:
			counts[3]++
		case memoryloop.StatusArchived:
			counts[4]++
		}
	}
	return counts
}

func (m memoriesModel) scopeCounts() [4]int {
	var counts [4]int
	if m.state == nil || m.state.Store == nil {
		return counts
	}
	for _, r := range m.state.Store.Records {
		if !m.matchesStatusFilter(r) {
			continue
		}
		counts[0]++ // all
		switch r.ScopeKind {
		case memoryloop.ScopeKindRepo:
			counts[1]++
		case memoryloop.ScopeKindMe:
			counts[2]++
		case memoryloop.ScopeKindBranch:
			counts[3]++
		}
	}
	return counts
}

func (m memoriesModel) renderDetail() string {
	r := m.selectedRecord()
	if r == nil {
		return ""
	}

	var out strings.Builder
	out.WriteString("  ")
	out.WriteString(m.styles.render(m.styles.sectionHeader, "DETAILS"))
	out.WriteString("\n")

	var b strings.Builder
	// Title line
	b.WriteString(m.styles.render(m.styles.title, r.Title))
	b.WriteString("\n\n")

	// Metadata line (kind, status, scope, origin)
	b.WriteString(kindStyle(m.styles, r.Kind)(string(r.Kind)))
	b.WriteString("  ")
	b.WriteString(statusDot(m.styles, r.Status))
	b.WriteString(" ")
	b.WriteString(string(r.Status))
	b.WriteString("  ")
	b.WriteString(m.styles.render(m.styles.dim, string(r.ScopeKind)))
	b.WriteString("  ")
	b.WriteString(m.styles.render(m.styles.dim, string(r.Origin)))

	// Body
	if r.Body != "" {
		b.WriteString("\n\n")
		b.WriteString(r.Body)
	}

	// Why
	if r.Why != "" {
		b.WriteString("\n\n")
		b.WriteString(m.styles.render(m.styles.dim, "WHY"))
		b.WriteString("\n")
		b.WriteString(r.Why)
	}

	// Stats
	b.WriteString("\n\n")
	stats := fmt.Sprintf("strength: %d/5 · injected: %dx · matched: %dx · last injected: %s · created: %s",
		r.Strength, r.InjectCount, r.MatchCount, timeAgo(r.LastInjectedAt), timeAgo(r.CreatedAt))
	b.WriteString(m.styles.render(m.styles.dim, stats))

	// Wrap in bordered card
	cardStyle := lipgloss.NewStyle().
		Border(lipgloss.RoundedBorder()).
		BorderForeground(lipgloss.Color("245")).
		Padding(1, 2).
		Width(m.width - 2)
	out.WriteString(cardStyle.Render(b.String()))
	return out.String()
}

func statusDotPlain(status memoryloop.Status) string {
	switch status {
	case memoryloop.StatusActive:
		return "\u25cf"
	case memoryloop.StatusCandidate:
		return "\u25cb"
	case memoryloop.StatusSuppressed:
		return "\u2715"
	case memoryloop.StatusArchived:
		return "\u25cc"
	default:
		return " "
	}
}

func truncate(s string, maxLen int) string {
	runes := []rune(s)
	if len(runes) <= maxLen {
		return s
	}
	return string(runes[:maxLen-1]) + "\u2026"
}

package memorylooptui

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/charmbracelet/bubbles/key"
	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/entireio/cli/cmd/entire/cli/memoryloop"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

const (
	tabMemories  = 0
	tabInjection = 1
	tabHistory   = 2
	tabSettings  = 3
	maxWidth     = 120
)

//nolint:recvcheck // bubbletea pattern: value receivers for interface, pointer for pushState mutation
type rootModel struct {
	ctx                 context.Context
	activeTab           int
	state               *memoryloop.State
	styles              tuiStyles
	width               int
	height              int
	showHelp            bool
	isRefreshing        bool
	spinner             spinner.Model
	err                 error
	flashText           string
	flashStyle          lipgloss.Style
	detailPage          *memoryDetailModel
	wizard              *wizardModel
	wizardActionHandler WizardActionHandler

	memoriesTab  memoriesModel
	injectionTab injectionModel
	historyTab   historyModel
	settingsTab  settingsModel
}

// Run launches the TUI program.
func Run(ctx context.Context, opts RunOptions) error {
	s := spinner.New()
	s.Spinner = spinner.Dot

	styles := newStyles()
	m := rootModel{
		ctx:                 ctx,
		styles:              styles,
		width:               maxWidth, // will be updated by tea.WindowSizeMsg
		spinner:             s,
		wizardActionHandler: opts.WizardActionHandler,
		memoriesTab:         newMemoriesModel(styles),
		injectionTab:        newInjectionModel(styles),
		historyTab:          newHistoryModel(styles),
	}

	p := tea.NewProgram(m, tea.WithAltScreen())
	_, err := p.Run()
	if err != nil {
		return fmt.Errorf("run TUI: %w", err)
	}
	return nil
}

func (m rootModel) Init() tea.Cmd {
	return func() tea.Msg {
		state, err := memoryloop.LoadState(m.ctx)
		return stateLoadedMsg{state: state, err: err}
	}
}

func (m rootModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	var cmds []tea.Cmd

	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = min(msg.Width, maxWidth)
		m.height = msg.Height
		m.memoriesTab.setSize(m.width, m.contentHeight())
		m.injectionTab.setSize(m.width, m.contentHeight())
		m.historyTab.setSize(m.width, m.contentHeight())
		m.settingsTab.setSize(m.width, m.contentHeight())
		if m.detailPage != nil {
			m.detailPage.setSize(m.width, m.contentHeight())
		}
		if m.wizard != nil && m.detailPage == nil {
			m.wizard.setSize(m.width, m.contentHeight())
		}
		return m, nil

	case tea.KeyMsg:
		if key.Matches(msg, globalKeyMap.Quit) {
			return m, tea.Quit
		}

		if m.detailPage != nil {
			var cmd tea.Cmd
			*m.detailPage, cmd = m.detailPage.update(msg)
			m.wizard = &m.detailPage.wizard
			if cmd != nil {
				cmds = append(cmds, cmd)
			}
			return m, tea.Batch(cmds...)
		}

		if m.wizard != nil {
			var cmd tea.Cmd
			*m.wizard, cmd = m.wizard.update(msg)
			if cmd != nil {
				cmds = append(cmds, cmd)
			}
			return m, tea.Batch(cmds...)
		}

		// When a sub-model is capturing input (add form, search, text input),
		// skip global key handling so Tab/Esc/number keys reach the sub-model.
		tabCapturesInput := (m.activeTab == tabMemories && m.memoriesTab.capturesInput()) ||
			(m.activeTab == tabInjection && m.injectionTab.inputFocus)

		if !tabCapturesInput {
			// Global keys -- check before delegating to tabs
			switch {
			case key.Matches(msg, globalKeyMap.Help):
				m.showHelp = !m.showHelp
				return m, nil
			case key.Matches(msg, globalKeyMap.TabNext):
				m.activeTab = (m.activeTab + 1) % 4
				return m, nil
			case key.Matches(msg, globalKeyMap.TabPrev):
				m.activeTab = (m.activeTab + 3) % 4
				return m, nil
			case key.Matches(msg, globalKeyMap.Tab1):
				m.activeTab = tabMemories
				return m, nil
			case key.Matches(msg, globalKeyMap.Tab2):
				m.activeTab = tabInjection
				return m, nil
			case key.Matches(msg, globalKeyMap.Tab3):
				m.activeTab = tabHistory
				return m, nil
			case key.Matches(msg, globalKeyMap.Tab4):
				m.activeTab = tabSettings
				return m, nil
			}
		}

	case stateLoadedMsg:
		if msg.err != nil {
			m.err = msg.err
			return m, nil
		}
		m.state = msg.state
		m.pushState()
		return m, nil

	case addMemoryMsg:
		return m.handleAddMemory(msg)

	case pruneMsg:
		return m.handlePrune()

	case settingsChangedMsg:
		return m.handleSettingsChanged(msg)

	case testPromptMsg:
		if m.state == nil || m.state.Store == nil {
			return m, nil
		}
		var selectOpts []memoryloop.SelectOption
		if len(m.state.Store.InjectionScopes) > 0 {
			selectOpts = append(selectOpts, memoryloop.WithInjectionScopes(m.state.Store.InjectionScopes))
		}
		matches := memoryloop.SelectRelevant(*m.state.Store, msg.prompt, time.Now(), selectOpts...)
		return m, func() tea.Msg { return testPromptResultMsg{matches: matches} }

	case refreshStartedMsg:
		if m.isRefreshing {
			return m, nil
		}
		m.isRefreshing = true
		// Full async refresh will be added in a later task.
		return m, func() tea.Msg {
			return flashMsg{text: "Refresh not yet implemented in TUI. Use: entire memory-loop refresh", success: false}
		}

	case wizardOpenMsg:
		m.showHelp = false
		m.detailPage = m.newDetailPage(msg.record)
		m.wizard = &m.detailPage.wizard
		return m, nil

	case wizardCloseMsg:
		m.detailPage = nil
		m.wizard = nil
		return m, nil

	case wizardResultMsg:
		return m.handleWizardResult(msg)

	case flashMsg:
		m.setFlash(msg.text, msg.success)
		return m, tea.Tick(2*time.Second, func(time.Time) tea.Msg { return clearFlashMsg{} })

	case clearFlashMsg:
		m.flashText = ""
		m.flashStyle = lipgloss.Style{}
		return m, nil
	}

	// Delegate to active tab
	var cmd tea.Cmd
	switch m.activeTab {
	case tabMemories:
		m.memoriesTab, cmd = m.memoriesTab.update(msg)
	case tabInjection:
		m.injectionTab, cmd = m.injectionTab.update(msg)
	case tabHistory:
		m.historyTab, cmd = m.historyTab.update(msg)
	case tabSettings:
		m.settingsTab, cmd = m.settingsTab.update(msg)
	}
	if cmd != nil {
		cmds = append(cmds, cmd)
	}

	return m, tea.Batch(cmds...)
}

func (m rootModel) View() string {
	if m.err != nil {
		return fmt.Sprintf("Error loading memory store: %v\nCheck .entire/memory-loop.json", m.err)
	}
	if m.state == nil {
		return "Loading..."
	}

	var b strings.Builder

	// Tab bar
	mode := memoryloop.ModeOff
	policy := memoryloop.ActivationPolicyReview
	if m.state.Store != nil {
		mode = m.state.Store.Mode
		policy = m.state.Store.ActivationPolicy
	}
	b.WriteString(renderTabBar(m.styles, m.activeTab, m.width, mode, policy))
	b.WriteString("\n")

	// Content area
	switch {
	case m.showHelp:
		b.WriteString(m.renderHelp())
	case m.detailPage != nil:
		b.WriteString(m.detailPage.view())
	case m.wizard != nil:
		b.WriteString(m.wizard.view())
	default:
		switch m.activeTab {
		case tabMemories:
			b.WriteString(m.memoriesTab.view())
		case tabInjection:
			b.WriteString(m.injectionTab.view())
		case tabHistory:
			b.WriteString(m.historyTab.view())
		case tabSettings:
			b.WriteString(m.settingsTab.view())
		}
	}

	// Status bar
	b.WriteString("\n")
	if m.flashText != "" {
		b.WriteString(m.styles.render(m.flashStyle, m.flashText))
	} else {
		hints := m.activeTabHints()
		info := m.activeTabInfo()
		b.WriteString(renderStatusBar(m.styles, hints, info, m.width))
	}

	return b.String()
}

func (m rootModel) contentHeight() int {
	// Total height minus tab bar (2) and status bar (1) and newlines (2)
	h := m.height - 5
	if h < 5 {
		h = 5
	}
	return h
}

func (m *rootModel) pushState() {
	m.memoriesTab.setState(m.state)
	m.injectionTab.setState(m.state)
	m.historyTab.setState(m.state)
	m.settingsTab.setState(m.state)
}

func (m rootModel) saveState() error {
	return memoryloop.SaveState(m.ctx, m.state) //nolint:wrapcheck // internal helper, callers wrap
}

func (m rootModel) handleAddMemory(msg addMemoryMsg) (tea.Model, tea.Cmd) {
	if m.state == nil || m.state.Store == nil || m.isRefreshing {
		return m, nil
	}
	updated, _, err := memoryloop.AddManualRecord(m.state.Store.Records, msg.input, time.Now())
	if err != nil {
		return m, func() tea.Msg { return flashMsg{text: err.Error(), success: false} }
	}
	m.state.Store.Records = updated
	if err := m.saveState(); err != nil {
		return m, func() tea.Msg { return flashMsg{text: fmt.Sprintf("save failed: %v", err), success: false} }
	}
	m.memoriesTab.setState(m.state)
	m.injectionTab.setState(m.state)
	m.historyTab.setState(m.state)
	m.settingsTab.setState(m.state)
	return m, nil
}

func (m rootModel) handlePrune() (tea.Model, tea.Cmd) {
	if m.state == nil || m.state.Store == nil || m.isRefreshing {
		return m, nil
	}
	updated, result := memoryloop.PruneRecords(m.state.Store.Records, time.Now())
	m.state.Store.Records = updated
	if err := m.saveState(); err != nil {
		return m, func() tea.Msg { return flashMsg{text: fmt.Sprintf("save failed: %v", err), success: false} }
	}
	m.memoriesTab.setState(m.state)
	m.injectionTab.setState(m.state)
	m.historyTab.setState(m.state)
	m.settingsTab.setState(m.state)
	msg := fmt.Sprintf("Pruned %d records", result.ArchivedCount)
	return m, func() tea.Msg { return flashMsg{text: msg, success: true} }
}

func (m rootModel) handleSettingsChanged(msg settingsChangedMsg) (tea.Model, tea.Cmd) {
	if m.state == nil || m.state.Store == nil {
		return m, nil
	}
	if msg.mode != nil {
		m.state.Store.Mode = *msg.mode
	}
	if msg.activationPolicy != nil {
		m.state.Store.ActivationPolicy = *msg.activationPolicy
	}
	if msg.maxInjected != nil {
		m.state.Store.MaxInjected = *msg.maxInjected
	}
	if msg.injectionScopes != nil {
		m.state.Store.InjectionScopes = *msg.injectionScopes
	}
	if err := m.saveState(); err != nil {
		return m, func() tea.Msg { return flashMsg{text: fmt.Sprintf("save failed: %v", err), success: false} }
	}
	m.memoriesTab.setState(m.state)
	m.injectionTab.setState(m.state)
	m.historyTab.setState(m.state)
	m.settingsTab.setState(m.state)
	return m, nil
}

func (m rootModel) newDetailPage(record memoryloop.MemoryRecord) *memoryDetailModel {
	detail := newMemoryDetailModel(m.styles, record, m.resolveWizardTargets)
	detail.setSize(m.width, m.contentHeight())
	return &detail
}

func (m rootModel) resolveWizardTargets(record memoryloop.MemoryRecord, location memoryloop.FileLocation) ([]string, error) {
	repoRoot, err := paths.WorktreeRoot(m.ctx)
	if err != nil {
		return nil, fmt.Errorf("resolve repo root: %w", err)
	}

	targets, err := memoryloop.ResolveFileTargetsForRecord(repoRoot, location, record, memoryloop.SkillTargetInput{})
	if err != nil {
		return nil, fmt.Errorf("resolve file targets: %w", err)
	}
	out := make([]string, 0, len(targets))
	for _, target := range targets {
		out = append(out, target.Path)
	}
	return out, nil
}

func (m rootModel) handleWizardResult(msg wizardResultMsg) (tea.Model, tea.Cmd) {
	if msg.success && m.wizardActionHandler != nil {
		return m.applyWizardRequest(msg.request, msg.flash)
	}

	switch msg.request.Intent {
	case WizardIntentSuppress:
		return m.handleWizardLifecycle(msg.request.RecordID, memoryloop.LifecycleActionSuppress, msg.flash)
	case WizardIntentArchive:
		return m.handleWizardLifecycle(msg.request.RecordID, memoryloop.LifecycleActionArchive, msg.flash)
	case WizardIntentAdopt, WizardIntentApply, "":
		if msg.success {
			m.detailPage = nil
			m.wizard = nil
		}
		m.setFlash(msg.flash, msg.success)
		return m, tea.Tick(2*time.Second, func(time.Time) tea.Msg { return clearFlashMsg{} })
	default:
		m.setFlash(fmt.Sprintf("unknown wizard action: %s", msg.request.Intent), false)
		return m, tea.Tick(2*time.Second, func(time.Time) tea.Msg { return clearFlashMsg{} })
	}
}

func (m rootModel) applyWizardRequest(request WizardRequest, successFlash string) (tea.Model, tea.Cmd) {
	flash, err := m.wizardActionHandler(m.ctx, request)
	if err != nil {
		m.setFlash(err.Error(), false)
		return m, tea.Tick(2*time.Second, func(time.Time) tea.Msg { return clearFlashMsg{} })
	}
	if strings.TrimSpace(flash) == "" {
		flash = successFlash
	}

	state, loadErr := memoryloop.LoadState(m.ctx)
	if loadErr != nil {
		m.setFlash(fmt.Sprintf("reload failed: %v", loadErr), false)
		return m, tea.Tick(2*time.Second, func(time.Time) tea.Msg { return clearFlashMsg{} })
	}

	m.state = state
	m.pushState()
	m.detailPage = nil
	m.wizard = nil
	m.setFlash(flash, true)
	return m, tea.Tick(2*time.Second, func(time.Time) tea.Msg { return clearFlashMsg{} })
}

func (m rootModel) handleWizardLifecycle(recordID string, action memoryloop.LifecycleAction, successFlash string) (tea.Model, tea.Cmd) {
	if m.state == nil || m.state.Store == nil || m.isRefreshing {
		return m, nil
	}

	updated, _, err := memoryloop.TransitionRecordLifecycle(m.state.Store.Records, recordID, action, time.Now().UTC())
	if err != nil {
		m.setFlash(err.Error(), false)
		return m, tea.Tick(2*time.Second, func(time.Time) tea.Msg { return clearFlashMsg{} })
	}

	m.state.Store.Records = updated
	if err := m.saveState(); err != nil {
		m.setFlash(fmt.Sprintf("save failed: %v", err), false)
		return m, tea.Tick(2*time.Second, func(time.Time) tea.Msg { return clearFlashMsg{} })
	}

	m.pushState()
	m.detailPage = nil
	m.wizard = nil
	m.setFlash(successFlash, true)
	return m, tea.Tick(2*time.Second, func(time.Time) tea.Msg { return clearFlashMsg{} })
}

func (m *rootModel) setFlash(text string, success bool) {
	m.flashText = text
	if success {
		m.flashStyle = m.styles.active
		return
	}
	m.flashStyle = m.styles.errorFlash
}

func (m rootModel) activeTabHints() string {
	if m.detailPage != nil {
		return m.detailPage.hints()
	}
	if m.wizard != nil {
		return m.wizard.hints()
	}
	switch m.activeTab {
	case tabMemories:
		return "j/k navigate · enter open detail · f filter · S scope · n new · ? help"
	case tabInjection:
		return "i focus input · enter test · esc unfocus · j/k navigate · ? help"
	case tabHistory:
		return "j/k navigate · R refresh · ? help"
	case tabSettings:
		return "m mode · p policy · +/- max injected · r/e/b toggle scopes · ? help"
	default:
		return "? help · q quit"
	}
}

func (m rootModel) activeTabInfo() string {
	if m.state == nil || m.state.Store == nil {
		return ""
	}
	switch m.activeTab {
	case tabMemories:
		return fmt.Sprintf("%d records", len(m.state.Store.Records))
	case tabInjection:
		return fmt.Sprintf("%d logs", len(m.state.InjectionLogs))
	case tabHistory:
		return fmt.Sprintf("%d refreshes", len(m.state.Store.RefreshHistory))
	default:
		return ""
	}
}

